/* Per-page Markdown actions: Copy / View / Open in Claude.
 * Exposes the raw .md the docs already publish (built by docs_hooks/llms_txt.py),
 * so this site is as consumable by an agent as it is by a human — fitting for a
 * tool whose product is an MCP server. Re-runs on Material's instant navigation. */
document$.subscribe(function () {
  var content = document.querySelector(".md-content__inner");
  if (!content) return;
  var h1 = content.querySelector("h1");
  if (!h1 || content.querySelector(".md-actions")) return;

  // Rendered pages use directory URLs (/x/); their source .md lives at /x.md,
  // and the site root maps to /index.md. The logo href gives the base path.
  var logo = document.querySelector(".md-header__button.md-logo");
  var base = logo ? new URL(logo.href).pathname : "/";
  var path = location.pathname;
  var mdUrl =
    path === base || path === base.replace(/\/$/, "")
      ? base.replace(/\/$/, "") + "/index.md"
      : path.replace(/\/$/, "") + ".md";

  var bar = document.createElement("div");
  bar.className = "md-actions";

  var copy = document.createElement("button");
  copy.type = "button";
  copy.className = "md-action";
  copy.textContent = "Copy as Markdown";
  copy.addEventListener("click", function () {
    fetch(mdUrl)
      .then(function (r) {
        return r.text();
      })
      .then(function (text) {
        return navigator.clipboard.writeText(text);
      })
      .then(function () {
        copy.textContent = "Copied ✓";
        setTimeout(function () {
          copy.textContent = "Copy as Markdown";
        }, 1600);
      })
      .catch(function () {
        copy.textContent = "Copy failed";
      });
  });

  var view = document.createElement("a");
  view.className = "md-action";
  view.href = mdUrl;
  view.textContent = "View as Markdown";

  var claude = document.createElement("a");
  claude.className = "md-action";
  claude.target = "_blank";
  claude.rel = "noopener";
  claude.href =
    "https://claude.ai/new?q=" +
    encodeURIComponent("Read " + location.origin + mdUrl + " and help me use model-ledger.");
  claude.textContent = "Open in Claude";

  bar.appendChild(copy);
  bar.appendChild(view);
  bar.appendChild(claude);
  h1.insertAdjacentElement("afterend", bar);
});

"""Tests for the optional ``get_models`` bulk-resolution backend method.

``get_models(hashes) -> {hash: ModelRef}`` is the batched counterpart to
``get_model``. Every shipped backend implements it, and ``batch_fallbacks``
supplies a protocol-only version for third-party backends that do not. These
tests pin the shared contract: same refs as one-by-one resolution, missing
hashes omitted, dedup, and empty/blank input handled.
"""

from __future__ import annotations

from pathlib import Path

import pytest

from model_ledger.backends import batch_fallbacks
from model_ledger.backends.json_files import JsonFileLedgerBackend
from model_ledger.backends.ledger_memory import InMemoryLedgerBackend
from model_ledger.backends.sqlite_ledger import SQLiteLedgerBackend
from model_ledger.core.ledger_models import ModelRef


def _make_model(name: str) -> ModelRef:
    return ModelRef(
        name=name,
        owner="risk-team",
        model_type="ml_model",
        tier="high",
        purpose="testing",
    )


def _seed(backend, names):
    refs = {}
    for n in names:
        ref = _make_model(n)
        backend.save_model(ref)
        refs[n] = ref
    return refs


def _backends(tmp_path: Path):
    sqlite = SQLiteLedgerBackend(str(tmp_path / "g.db"))
    json_files = JsonFileLedgerBackend(str(tmp_path / "jf"))
    return {
        "memory": InMemoryLedgerBackend(),
        "sqlite": sqlite,
        "json_files": json_files,
    }


@pytest.fixture(params=["memory", "sqlite", "json_files"])
def backend(request, tmp_path):
    return _backends(tmp_path)[request.param]


class TestGetModels:
    def test_resolves_all_hashes(self, backend):
        refs = _seed(backend, ["a", "b", "c"])
        result = backend.get_models([refs["a"].model_hash, refs["b"].model_hash])
        assert set(result) == {refs["a"].model_hash, refs["b"].model_hash}
        assert result[refs["a"].model_hash].name == "a"
        assert result[refs["b"].model_hash].name == "b"

    def test_omits_missing_hashes(self, backend):
        refs = _seed(backend, ["a"])
        result = backend.get_models([refs["a"].model_hash, "deadbeef-missing"])
        assert set(result) == {refs["a"].model_hash}

    def test_empty_and_blank_input(self, backend):
        _seed(backend, ["a"])
        assert backend.get_models([]) == {}
        assert backend.get_models(["", ""]) == {}

    def test_dedup_repeated_hash(self, backend):
        refs = _seed(backend, ["a"])
        h = refs["a"].model_hash
        result = backend.get_models([h, h, h])
        assert set(result) == {h}

    def test_parity_with_single_get_model(self, backend):
        refs = _seed(backend, ["a", "b", "c"])
        hashes = [r.model_hash for r in refs.values()]
        bulk = backend.get_models(hashes)
        for h in hashes:
            single = backend.get_model(h)
            assert bulk[h].model_hash == single.model_hash
            assert bulk[h].name == single.name


class TestGetModelsFallback:
    """The protocol-only fallback must match the native implementations."""

    def test_fallback_resolves_and_omits(self):
        backend = InMemoryLedgerBackend()
        refs = _seed(backend, ["a", "b"])
        result = batch_fallbacks.get_models(
            backend, [refs["a"].model_hash, "missing", refs["b"].model_hash]
        )
        assert set(result) == {refs["a"].model_hash, refs["b"].model_hash}

    def test_fallback_dedups_and_skips_blank(self):
        backend = InMemoryLedgerBackend()
        refs = _seed(backend, ["a"])
        h = refs["a"].model_hash
        result = batch_fallbacks.get_models(backend, ["", h, h])
        assert set(result) == {h}

"""Tests for DataNode and DataPort."""

from model_ledger.graph.models import DataNode, DataPort


class TestDataPort:
    def test_create(self):
        p = DataPort("my_table")
        assert p.identifier == "my_table"
        assert p.schema == {}

    def test_lowercases(self):
        assert DataPort("ANALYTICS.EVENTS.TABLE").identifier == "analytics.events.table"

    def test_equality(self):
        assert DataPort("table_a") == DataPort("table_a")

    def test_case_insensitive(self):
        assert DataPort("TABLE_A") == DataPort("table_a")

    def test_inequality(self):
        assert DataPort("table_a") != DataPort("table_b")

    def test_matching_schema(self):
        assert DataPort("t", model_name="a") == DataPort("t", model_name="a")

    def test_different_schema(self):
        assert DataPort("t", model_name="a") != DataPort("t", model_name="b")

    def test_one_no_schema(self):
        # A port with schema must NOT match a bare port — prevents false edges
        assert DataPort("t", model_name="a") != DataPort("t")

    def test_like_pattern(self):
        assert DataPort("s", model_name="tm-%") == DataPort("s", model_name="tm-m2o")

    def test_like_no_match(self):
        assert DataPort("s", model_name="tm-%") != DataPort("s", model_name="uup-gambling")

    def test_hashable(self):
        assert len({DataPort("a"), DataPort("a"), DataPort("b")}) == 2

    def test_repr_with_schema(self):
        r = repr(DataPort("table", model_name="x"))
        assert "table" in r and "model_name" in r

    def test_repr_simple(self):
        assert "table" in repr(DataPort("table"))


class TestDataNode:
    def test_string_inputs(self):
        node = DataNode("scorer", inputs=["a", "b"], outputs=["c"])
        assert len(node.inputs) == 2
        assert all(isinstance(p, DataPort) for p in node.inputs)

    def test_dataport_inputs(self):
        node = DataNode("scorer", inputs=[DataPort("a")])
        assert node.inputs[0].identifier == "a"

    def test_mixed_inputs(self):
        node = DataNode("scorer", inputs=["a", DataPort("b", model_name="x")])
        assert node.inputs[1].schema == {"model_name": "x"}

    def test_defaults(self):
        node = DataNode("simple")
        assert node.platform == "" and node.inputs == [] and node.outputs == []

    def test_metadata(self):
        node = DataNode("s", metadata={"owner": "team"})
        assert node.metadata["owner"] == "team"

