        from model_ledger.mcp.server import create_server

        with pytest.raises(TypeError, match="LedgerBackend"):
            create_server(backend="./ledger.db")

    def test_accepts_real_backend(self):
        from model_ledger.backends.ledger_memory import InMemoryLedgerBackend
        from model_ledger.mcp.server import create_server

        server = create_server(backend=InMemoryLedgerBackend())
        assert server is not None

    def test_accepts_partial_custom_backend(self):
        """Duck typing, not full-protocol isinstance — partial third-party
        backends that worked on 0.7.12 must keep working."""
        from model_ledger.backends.ledger_memory import InMemoryLedgerBackend
        from model_ledger.mcp.server import create_server

        class PartialBackend:
            def __init__(self):
                self._i = InMemoryLedgerBackend()

            def save_model(self, m):
                return self._i.save_model(m)

            def get_model(self, h):
                return self._i.get_model(h)

            def get_model_by_name(self, n):
                return self._i.get_model_by_name(n)

            def list_models(self, **f):
                return self._i.list_models(**f)

            def append_snapshot(self, s):
                return self._i.append_snapshot(s)

            def list_snapshots(self, h, **f):
                return self._i.list_snapshots(h, **f)

            def latest_snapshot(self, h, tag=None):
                return self._i.latest_snapshot(h, tag)

            # deliberately missing: update_model, get_snapshot,
            # list_snapshots_before, set_tag, get_tag, list_tags

        assert create_server(backend=PartialBackend()) is not None

    def test_rejects_object_missing_core_methods(self):
        from model_ledger.mcp.server import create_server

        with pytest.raises(TypeError, match="LedgerBackend"):
            create_server(backend=object())

"""Introspector registry with lazy entry point discovery."""

from __future__ import annotations

from typing import Any

from model_ledger.core.exceptions import NoIntrospectorError
from model_ledger.introspect.protocol import Introspector

ENTRY_POINT_GROUP = "model_ledger.introspectors"

_registry: IntrospectorRegistry | None = None


class IntrospectorRegistry:
    def __init__(self) -> None:
        self._introspectors: list[Introspector] = []
        self._discovered = False

    def register(self, introspector: Introspector) -> None:
        """Register an introspector. Deduplicates by name. Prepends for priority."""
        self._introspectors = [i for i in self._introspectors if i.name != introspector.name]
        self._introspectors.insert(0, introspector)

    def find(self, obj: Any) -> Introspector:
        """Find first introspector that can handle obj."""
        self._ensure_discovered()
        for intro in self._introspectors:
            if intro.can_handle(obj):
                return intro
        raise NoIntrospectorError(type(obj))

    def get_by_name(self, name: str) -> Introspector:
        """Get introspector by name."""
        self._ensure_discovered()
        for intro in self._introspectors:
            if intro.name == name:
                return intro
        raise NoIntrospectorError(name)

    def _ensure_discovered(self) -> None:
        """Lazy-load entry points on first use."""
        if self._discovered:
            return
        self._discovered = True
        try:
            from importlib.metadata import entry_points

            eps = entry_points(group=ENTRY_POINT_GROUP)
            for ep in sorted(eps, key=lambda e: e.name):
                try:
                    cls = ep.load()
                    instance = cls()
                    if not any(i.name == instance.name for i in self._introspectors):
                        self._introspectors.append(instance)
                except Exception:
                    pass
        except Exception:
            pass


def get_registry() -> IntrospectorRegistry:
    """Get or create the global introspector registry."""
    global _registry
    if _registry is None:
        _registry = IntrospectorRegistry()
    return _registry


def reset_registry() -> None:
    """Reset the global registry. Used in tests."""
    global _registry
    _registry = None


def register_introspector(introspector: Introspector) -> None:
    """Convenience function to register an introspector globally."""
    get_registry().register(introspector)

"""XGBoost introspector."""

from __future__ import annotations

from typing import Any

from model_ledger.introspect.models import FeatureInfo, IntrospectionResult


class XGBoostIntrospector:
    name = "xgboost"

    def can_handle(self, obj: Any) -> bool:
        try:
            import xgboost as xgb

            return isinstance(obj, (xgb.Booster, xgb.XGBModel))
        except ImportError:
            return False

    def introspect(self, obj: Any) -> IntrospectionResult:
        import xgboost as xgb

        if isinstance(obj, xgb.XGBModel):
            params = obj.get_params()
            features = []
            if hasattr(obj, "feature_names_in_"):
                features = [FeatureInfo(name=str(n)) for n in obj.feature_names_in_]
            metrics = {}
            if hasattr(obj, "best_score") and obj.best_score is not None:
                metrics["best_score"] = obj.best_score
            return IntrospectionResult(
                introspector=self.name,
                framework="xgboost",
                algorithm=type(obj).__name__,
                hyperparameters=params,
                features=features,
                metrics=metrics,
            )

        # Raw Booster
        features = []
        if obj.feature_names:
            features = [FeatureInfo(name=n) for n in obj.feature_names]
        config = obj.save_config()
        return IntrospectionResult(
            introspector=self.name,
            framework="xgboost",
            algorithm="Booster",
            features=features,
            metadata={"config": config},
        )

